export class RunDrawerComponent {
  readonly run = input<RunDetailVM | null>(null);
  readonly close = output<void>();

  protected readonly tabs: readonly DrawerTab[] = [
    'Overview',
    'Tasks',
    'Metrics',
    'Config',
    'Logs',
  ];
  protected readonly activeTab = signal<DrawerTab>('Overview');
  protected readonly copiedTarget = signal<CopyTarget | null>(null);

  // Kept mounted for the duration of the exit transition after `run()` goes
  // null — `@if` would otherwise destroy the drawer instantly, skipping it.
  protected readonly displayRun = signal<RunDetailVM | null>(null);
  // Target open/closed visual state — toggling this (rather than a one-shot
  // keyframe animation) is what actually drives the slide/fade transition,
  // so enter and exit go through the exact same mechanism.
  protected readonly visible = signal(false);
  protected readonly closing = signal(false);

  private readonly document = inject(DOCUMENT);
  private readonly destroyRef = inject(DestroyRef);
  private readonly closeButton = viewChild<ElementRef<HTMLButtonElement>>('closeButton');
  private previouslyOpen = false;
  private opener: HTMLElement | null = null;
  private copyTimer: ReturnType<typeof setTimeout> | null = null;
  private closeAnimationTimer: ReturnType<typeof setTimeout> | null = null;
  private enterTimer: ReturnType<typeof setTimeout> | null = null;

  protected readonly copyableError = computed(() => {
    const selectedRun = this.displayRun();
    return selectedRun?.error?.raw ?? selectedRun?.commandLine ?? '';
  });

  protected readonly attentionSummary = computed(() => {
    const selectedRun = this.displayRun();
    const failed = selectedRun?.tasks?.failed ?? 0;
    const retries = selectedRun?.retries ?? 0;
    const details: string[] = [];
    if (failed) details.push(`${failed} ${failed === 1 ? 'task' : 'tasks'} failed`);
    if (retries) details.push(`${retries} ${retries === 1 ? 'retry' : 'retries'}`);
    return details.length ? details.join(', ') : 'This run needs attention';
  });

  protected readonly runningSummary = computed(() => {
    const tasks = this.displayRun()?.tasks;
    if (!tasks) return 'Waiting for task data.';
    return `${tasks.succeeded} succeeded · ${tasks.running ?? 0} running of ${tasks.total} tasks`;
  });

  constructor() {
    effect(() => {
      const isOpen = this.run() !== null;
      if (isOpen && !this.previouslyOpen) {
        this.opener =
          this.document.activeElement instanceof HTMLElement ? this.document.activeElement : null;
        queueMicrotask(() => this.closeButton()?.nativeElement.focus());
      } else if (!isOpen && this.previouslyOpen) {
        queueMicrotask(() => this.opener?.focus());
        this.activeTab.set('Overview');
      }
      this.previouslyOpen = isOpen;
    });

    // Drives mount → visible → hidden → unmount, staying one or two ticks
    // behind `run()` so both the enter and exit transitions get to play.
    // Enter: mount first (still off-screen/transparent — that's just the
    // element's plain declared CSS, not a JS-applied style, so it needs no
    // extra step to "commit"), then flip `visible` on the next macrotask so
    // the transition to the open position actually runs. A macrotask
    // (rather than requestAnimationFrame) is used deliberately: rAF can be
    // paused indefinitely on a backgrounded/inactive tab, which would leave
    // the drawer stuck off-screen; setTimeout always fires. Exit is the
    // mirror: flip `visible` off immediately, unmount only once the
    // transition duration elapses.
    effect(() => {
      const incoming = this.run();

      if (this.closeAnimationTimer) {
        clearTimeout(this.closeAnimationTimer);
        this.closeAnimationTimer = null;
      }
      if (this.enterTimer) {
        clearTimeout(this.enterTimer);
        this.enterTimer = null;
      }

      const reducedMotion =
        this.document.defaultView?.matchMedia('(prefers-reduced-motion: reduce)').matches ?? false;

      if (incoming) {
        this.closing.set(false);
        this.displayRun.set(incoming);
        if (reducedMotion) {
          this.visible.set(true);
          return;
        }
        this.visible.set(false);
        this.enterTimer = setTimeout(() => {
          this.visible.set(true);
          this.enterTimer = null;
        }, 0);
        return;
      }

      if (this.displayRun() === null) return;

      this.visible.set(false);
      if (reducedMotion) {
        this.displayRun.set(null);
        return;
      }

      this.closing.set(true);
      this.closeAnimationTimer = setTimeout(() => {
        this.displayRun.set(null);
        this.closing.set(false);
        this.closeAnimationTimer = null;
      }, 180);
    });

    this.destroyRef.onDestroy(() => {
      if (this.copyTimer) clearTimeout(this.copyTimer);
      if (this.closeAnimationTimer) clearTimeout(this.closeAnimationTimer);
      if (this.enterTimer) clearTimeout(this.enterTimer);
      this.opener?.focus();
    });
  }

  @HostListener('document:keydown.escape')
  protected onEscape(): void {
    if (this.run()) this.requestClose();
  }

  protected requestClose(): void {
    this.close.emit();
  }

  protected selectTab(tab: DrawerTab): void {
    this.activeTab.set(tab);
  }

  protected onTabKeydown(event: KeyboardEvent): void {
    const currentIndex = this.tabs.indexOf(this.activeTab());
    let nextIndex: number | null = null;

    if (event.key === 'ArrowRight') nextIndex = (currentIndex + 1) % this.tabs.length;
    if (event.key === 'ArrowLeft')
      nextIndex = (currentIndex - 1 + this.tabs.length) % this.tabs.length;
    if (event.key === 'Home') nextIndex = 0;
    if (event.key === 'End') nextIndex = this.tabs.length - 1;
    if (nextIndex === null) return;

    event.preventDefault();
    this.activeTab.set(this.tabs[nextIndex]);
    const tabList = event.currentTarget as HTMLElement;
    queueMicrotask(() => {
      tabList.querySelectorAll<HTMLButtonElement>('[role="tab"]')[nextIndex!]?.focus();
    });
  }

  protected copyError(): void {
    const value = this.copyableError();
    if (value) this.copy(value, 'error');
  }

  protected copyWorkDir(): void {
    const value = this.displayRun()?.workDir;
    if (value && value !== '—') this.copy(value, 'workDir');
  }

  protected placeholderIcon(): string {
    const icons: Record<Exclude<DrawerTab, 'Overview'>, string> = {
      Tasks: 'checklist',
      Metrics: 'query_stats',
      Config: 'tune',
      Logs: 'subject',
    };
    const tab = this.activeTab();
    return tab === 'Overview' ? 'info' : icons[tab];
  }

  private copy(value: string, target: CopyTarget): void {
    this.copiedTarget.set(target);
    void this.document.defaultView?.navigator.clipboard?.writeText(value).catch(() => undefined);

    if (this.copyTimer) clearTimeout(this.copyTimer);
    this.copyTimer = setTimeout(() => this.copiedTarget.set(null), 1200);
  }
}

styleUrlsData.data:
:host {
  position: absolute;
  inset: 0;
  display: block;
  overflow: hidden;
  color: var(--c-text);
  // Host element exists even when no run is selected (only its content is
  // conditional) — without this, the empty, invisible drawer still covers
  // the whole page and swallows clicks meant for the runs table underneath.
  pointer-events: none;
  // Must beat the runs table's sticky header (z-index: 2), which otherwise
  // paints above the drawer since both are position:absolute/sticky
  // descendants with no shared ancestor stacking context.
  z-index: 20;
}

// Enter and exit share the same transition-driven mechanism (rather than
// keyframe animations that only play once, on mount) so both feel the same:
// the component toggles `--visible` a frame after mount to slide/fade in,
// and clears it to slide/fade out, unmounting only once the transition ends.
//
// The entering curve below is the exact time-reverse of --ease-in
// (cubic-bezier(x1,y1,x2,y2) reversed is (1-x2,1-y2,1-x1,1-y1)) rather than
// the global --ease-out token. --ease-out and --ease-in aren't mirrors of
// each other, so pairing them made the exit visibly start slow while the
// entrance front-loaded most of its travel in the first ~50ms — reading as
// a slide out but a pop in. Mirroring the exit curve makes the entrance
// genuinely feel like the same motion played backward.
$drawer-enter-ease: cubic-bezier(0, 0, 0.6, 1);

.scrim {
  position: absolute;
  inset: 0;
  background: rgb(11 31 51 / 28%);
  opacity: 0;
  transition: opacity var(--motion-base) #{$drawer-enter-ease};
  pointer-events: auto;

  &--visible {
    opacity: 1;
  }

  &--closing {
    transition-timing-function: var(--ease-in);
  }
}

.drawer {
  position: absolute;
  inset: 0 0 0 auto;
  display: flex;
  width: min(680px, 100%);
  flex-direction: column;
  background: var(--c-surface);
  border-left: 1px solid var(--c-border);
  box-shadow: -12px 0 32px rgb(11 31 51 / 14%);
  outline: 0;
  pointer-events: auto;
  transform: translateX(100%);
  transition: transform var(--motion-base) #{$drawer-enter-ease};

  &--visible {
    transform: translateX(0);
  }

  &--closing {
    transition-timing-function: var(--ease-in);
  }
}

.drawer__header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
  padding: 20px 20px 16px 24px;
  border-bottom: 1px solid var(--c-border);
}

.drawer__status {
  padding-top: 3px;
}

.drawer__identity {
  min-width: 0;

  h2 {
    overflow: hidden;
    margin: 0;
    color: var(--c-text);
    font-size: 1.1rem;
    font-weight: 650;
    line-height: 1.4;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

.drawer__context {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  align-items: center;
  margin-top: 4px;
  color: #526477;
  font-size: 0.82rem;
}

.tag {
  padding: 1px 7px;
  color: #475569;
  background: var(--c-cancel-bg);
  border: 1px solid var(--c-cancel-border);
  border-radius: 100px;
  font-size: 0.72rem;
}

.drawer__actions {
  display: flex;
  gap: 2px;
}

.icon-button,
.copy-icon {
  display: inline-grid;
  width: 36px;
  height: 36px;
  padding: 0;
  place-items: center;
  color: #475569;
  background: transparent;
  border: 0;
  border-radius: var(--radius);
  cursor: pointer;

  &:hover {
    color: var(--c-text);
    background: #f1f4f7;
  }

  &:focus-visible {
    outline: 2px solid var(--c-primary);
    outline-offset: 2px;
  }

  .material-icons {
    font-size: 20px;
  }
}

.icon-button--close {
  margin-left: 4px;
}

.tabs {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  padding: 0 20px;
  border-bottom: 1px solid var(--c-border);
}

.tabs__tab {
  position: relative;
  padding: 12px 10px 10px;
  color: #526477;
  background: transparent;
  border: 0;
  cursor: pointer;
  font: inherit;
  font-size: 0.84rem;
  font-weight: 550;
  white-space: nowrap;

  &[aria-selected='true'] {
    color: #3346c8;

    &::after {
      position: absolute;
      right: 8px;
      bottom: -1px;
      left: 8px;
      height: 2px;
      background: var(--c-primary);
      content: '';
    }
  }

  &:focus-visible {
    outline: 2px solid var(--c-primary);
    outline-offset: -2px;
  }
}

.drawer__body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  background: #fbfcfd;

  &:focus-visible {
    outline: 2px solid var(--c-primary);
    outline-offset: -3px;
  }
}

.overview {
  display: grid;
  gap: 12px;
  padding: 20px 24px 32px;
}

.result-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  padding: 16px;
  border: 1px solid;
  border-radius: var(--radius);

  h3 {
    margin: 0;
    font-size: 0.92rem;
    font-weight: 650;
  }

  p {
    margin: 6px 0 0;
  }
}

.result-card__icon {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;

  .material-icons {
    font-size: 21px;
  }
}

.result-card--failed {
  color: var(--c-fail-text);
  background: var(--c-fail-bg);
  border-color: var(--c-fail-border);

  .error-cause {
    color: #851d1d;
    font-family: 'JetBrains Mono Variable', ui-monospace, monospace;
    font-size: 0.82rem;
    line-height: 1.5;
  }
}

.result-card--succeeded {
  color: var(--c-ok-text);
  background: var(--c-ok-bg);
  border-color: var(--c-ok-border);
}

.result-card--running {
  color: var(--c-run-text);
  background: var(--c-run-bg);
  border-color: var(--c-run-border);
}

.result-card__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.button {
  display: inline-flex;
  min-height: 34px;
  gap: 6px;
  align-items: center;
  padding: 6px 10px;
  color: var(--c-text);
  background: var(--c-surface);
  border: 1px solid #c8d1dc;
  border-radius: var(--radius);
  cursor: pointer;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 600;

  .material-icons {
    font-size: 16px;
  }

  &:focus-visible {
    outline: 2px solid var(--c-primary);
    outline-offset: 2px;
  }
}

.button--secondary {
  color: #3346c8;
  border-color: #aeb8f4;
}

.button--disabled {
  color: #68788a;
  background: #f1f3f5;
  border-color: #d9dee4;
  cursor: not-allowed;
}

.attention-note {
  display: flex;
  gap: 6px;
  align-items: center;
  padding-top: 8px;
  color: #92400e;
  border-top: 1px solid var(--c-warn-border);
  font-size: 0.82rem;

  .material-icons {
    font-size: 17px;
  }
}

.section {
  padding: 16px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);

  > h3 {
    margin: 0 0 14px;
    color: var(--c-text);
    font-size: 0.86rem;
    font-weight: 650;
  }
}

.metadata-grid,
.task-stats,
.resource-stats {
  display: grid;
  margin: 0;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px 20px;

  div {
    min-width: 0;
  }

  dt {
    margin-bottom: 3px;
    color: #5d6d7e;
    font-size: 0.72rem;
    font-weight: 550;
  }

  dd {
    min-width: 0;
    margin: 0;
    color: var(--c-text);
    font-size: 0.82rem;
    font-variant-numeric: tabular-nums;
  }
}

.metadata-grid__wide {
  grid-column: 1 / -1;
}

.copy-value {
  display: flex;
  gap: 8px;
  align-items: center;

  > span {
    overflow: hidden;
    font-family: 'JetBrains Mono Variable', ui-monospace, monospace;
    font-size: 0.76rem;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

.copy-icon {
  width: 28px;
  height: 28px;
  flex: 0 0 auto;

  .material-icons {
    font-size: 16px;
  }
}

.task-overview__bar {
  display: flex;
  margin-bottom: 16px;
}

.task-stats {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
}

.stat {
  font-weight: 650;
}

.stat--succeeded {
  color: var(--c-ok-text) !important;
}

.stat--failed {
  color: var(--c-fail-text) !important;
}

