  dd {
    font-size: 1rem;
    font-weight: 650;
  }
}

.empty-note {
  margin: 0;
  color: #5d6d7e;
  font-size: 0.82rem;
}

.process-list {
  display: grid;
  gap: 12px;
}

.process {
  display: grid;
  grid-template-columns: minmax(110px, 1fr) minmax(100px, 2fr) 42px;
  gap: 12px;
  align-items: center;
  font-size: 0.78rem;
}

.process__name {
  overflow: hidden;
  color: var(--c-text);
  font-family: 'JetBrains Mono Variable', ui-monospace, monospace;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.process__track {
  height: 7px;
  overflow: hidden;
  background: #e3e8ee;
  border-radius: 4px;
}

.process__fill {
  display: block;
  height: 100%;
  background: var(--c-primary);
  border-radius: inherit;
}

.process__value {
  color: #526477;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.placeholder {
  display: grid;
  min-height: 360px;
  padding: 48px 24px;
  align-content: center;
  justify-items: center;
  color: #526477;
  text-align: center;

  h3 {
    margin: 12px 0 4px;
    color: var(--c-text);
    font-size: 1rem;
  }

  p {
    margin: 0;
  }
}

.placeholder__icon {
  color: #64748b;
  font-size: 32px;
}

@media (max-width: 560px) {
  .drawer__header {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .drawer__status {
    grid-column: 1 / -1;
  }

  .metadata-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .task-stats,
  .resource-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .process {
    grid-template-columns: minmax(90px, 1fr) minmax(70px, 1fr) 38px;
    gap: 8px;
  }
}

