import { DOCUMENT } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  DestroyRef,
  computed,
  effect,
  inject,
  input,
  output,
  signal,
} from '@angular/core';
import { MatDrawer, MatDrawerContainer, MatDrawerContent } from '@angular/material/sidenav';
import { StatusPillComponent } from '../../../shared/status-pill/status-pill.component';
import { TaskBarComponent } from '../../../shared/task-bar/task-bar.component';
import type { RunDetailVM } from '../run-drawer/run-drawer.models';

type DrawerTab = 'Overview' | 'Tasks' | 'Metrics' | 'Config' | 'Logs';
type CopyTarget = 'error' | 'workDir';

@Component({
  selector: 'app-run-drawer-material',
  standalone: true,
  imports: [MatDrawerContainer, MatDrawer, MatDrawerContent, StatusPillComponent, TaskBarComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <mat-drawer-container class="run-drawer-material" [hasBackdrop]="true">
      <mat-drawer-content class="run-drawer-material__content"></mat-drawer-content>

      <mat-drawer
        class="run-drawer-material__panel"
        mode="over"
        position="end"
        autoFocus="first-heading"
        role="dialog"
        aria-modal="true"
        [attr.aria-labelledby]="displayRun() ? 'run-drawer-material-title' : null"
        [opened]="isOpen()"
        (openedChange)="onOpenedChange($event)"
        (closed)="onClosed()"
      >
        @if (displayRun(); as selectedRun) {
          <header class="drawer__header">
            <div class="drawer__status">
              <app-status-pill
                [status]="selectedRun.status"
                [exitLabel]="
                  selectedRun.exitStatus === null ? null : selectedRun.exitStatus.toString()
                "
              />
            </div>

            <div class="drawer__identity">
              <h2 id="run-drawer-material-title" [title]="selectedRun.name">{{ selectedRun.name }}</h2>
              <div class="drawer__context">
                <span>{{ selectedRun.pipeline }}</span>
                @if (selectedRun.executor) {
                  <span class="tag">{{ selectedRun.executor }}</span>
                }
              </div>
            </div>

            <div class="drawer__actions">
              <button class="icon-button" type="button" aria-label="Star run">
                <span class="material-icons" aria-hidden="true">star_border</span>
              </button>
              <button class="icon-button" type="button" aria-label="More run actions">
                <span class="material-icons" aria-hidden="true">more_vert</span>
              </button>
              <button
                class="icon-button icon-button--close"
                type="button"
                aria-label="Close run details"
                (click)="requestClose()"
              >
                <span class="material-icons" aria-hidden="true">close</span>
              </button>
            </div>
          </header>

          <div
            class="tabs"
            role="tablist"
            aria-label="Run detail sections"
            (keydown)="onTabKeydown($event)"
          >
            @for (tab of tabs; track tab) {
              <button
                class="tabs__tab"
                type="button"
                role="tab"
                [id]="'run-tab-material-' + tab.toLowerCase()"
                [attr.aria-selected]="activeTab() === tab"
                aria-controls="run-drawer-material-panel"
                [tabIndex]="activeTab() === tab ? 0 : -1"
                (click)="selectTab(tab)"
              >
                {{ tab }}
              </button>
            }
          </div>

          <div
            class="drawer__body"
            role="tabpanel"
            id="run-drawer-material-panel"
            [attr.aria-labelledby]="'run-tab-material-' + activeTab().toLowerCase()"
            tabindex="0"
          >
            @if (activeTab() === 'Overview') {
              <div class="overview">
                @if (selectedRun.status === 'FAILED') {
                  <section class="result-card result-card--failed" aria-labelledby="error-heading-material">
                    <div class="result-card__icon" aria-hidden="true">
                      <span class="material-icons">error</span>
                    </div>
                    <div class="result-card__content">
                      <h3 id="error-heading-material">
                        Error
                        @if (selectedRun.error?.process) {
                          <span>· process {{ selectedRun.error?.process }}</span>
                        }
                      </h3>
                      @if (selectedRun.error?.cause; as cause) {
                        <p class="error-cause">{{ cause }}</p>
                      } @else {
                        <p>This run failed but reported no error message.</p>
                      }
                      <div class="result-card__actions">
                        @if (copyableError()) {
                          <button
                            class="button button--secondary"
                            type="button"
                            (click)="copyError()"
                          >
                            <span class="material-icons" aria-hidden="true">
                              {{ copiedTarget() === 'error' ? 'check' : 'content_copy' }}
                            </span>
                            {{ copiedTarget() === 'error' ? 'Copied!' : 'Copy' }}
                          </button>
                        }
                        <button class="button button--disabled" type="button" disabled>
                          ✨ Explain error (AI) — coming soon
                        </button>
                      </div>
                    </div>
                  </section>
                } @else if (selectedRun.status === 'SUCCEEDED') {
                  <section
                    class="result-card result-card--succeeded"
                    aria-label="Run completed successfully"
                  >
                    <div class="result-card__icon" aria-hidden="true">
                      <span class="material-icons">check_circle</span>
                    </div>
                    <div class="result-card__content">
                      <h3>Run completed successfully</h3>
                      <p>All workflow stages completed in {{ selectedRun.durationLabel }}.</p>
                      @if (selectedRun.needsAttention) {
                        <p class="attention-note">
                          <span class="material-icons" aria-hidden="true">warning_amber</span>
                          {{ attentionSummary() }}
                        </p>
                      }
                    </div>
                  </section>
                } @else if (selectedRun.status === 'RUNNING') {
                  <section class="result-card result-card--running" aria-label="Run in progress">
                    <div class="result-card__icon" aria-hidden="true">
                      <span class="material-icons">sync</span>
                    </div>
                    <div class="result-card__content">
                      <h3>Run in progress</h3>
                      <p>{{ runningSummary() }}</p>
                    </div>
                  </section>
                }

                <section class="section" aria-labelledby="metadata-heading-material">
                  <h3 id="metadata-heading-material">Metadata</h3>
                  <dl class="metadata-grid">
                    <div>
                      <dt>User</dt>
                      <dd>{{ selectedRun.user ?? '—' }}</dd>
                    </div>
                    <div>
                      <dt>Submitted</dt>
                      <dd>{{ selectedRun.submittedLabel }}</dd>
                    </div>
                    <div>
                      <dt>Started</dt>
                      <dd>{{ selectedRun.startedLabel }}</dd>
                    </div>
                    <div>
                      <dt>Completed</dt>
                      <dd>{{ selectedRun.completedLabel }}</dd>
                    </div>
                    <div>
                      <dt>Duration</dt>
                      <dd>{{ selectedRun.durationLabel }}</dd>
                    </div>
                    <div>
                      <dt>Exit status</dt>
                      <dd>{{ selectedRun.exitStatus ?? '—' }}</dd>
                    </div>
                    <div class="metadata-grid__wide">
                      <dt>Work directory</dt>
                      <dd class="copy-value">
                        <span [title]="selectedRun.workDir">{{ selectedRun.workDir }}</span>
                        @if (selectedRun.workDir !== '—') {
                          <button
                            class="copy-icon"
                            type="button"
                            [attr.aria-label]="
                              copiedTarget() === 'workDir'
                                ? 'Work directory copied'
                                : 'Copy work directory'
                            "
                            (click)="copyWorkDir()"
                          >
                            <span class="material-icons" aria-hidden="true">
                              {{ copiedTarget() === 'workDir' ? 'check' : 'content_copy' }}
                            </span>
                          </button>
                        }
                      </dd>
                    </div>
                  </dl>
                </section>

                <section class="section" aria-labelledby="tasks-heading-material">
                  <h3 id="tasks-heading-material">
                    {{ selectedRun.status === 'RUNNING' ? 'Task progress' : 'Task breakdown' }}
                  </h3>
                  @if (selectedRun.tasks; as tasks) {
                    <app-task-bar class="task-overview__bar" [breakdown]="tasks" />
                    <dl class="task-stats">
                      <div>
                        <dt>Succeeded</dt>
                        <dd class="stat stat--succeeded">{{ tasks.succeeded }}</dd>
                      </div>
                      @if (selectedRun.status === 'RUNNING') {
                        <div>
                          <dt>Running</dt>
                          <dd class="stat stat--running">{{ tasks.running ?? 0 }}</dd>
                        </div>
                      }
                      <div>
                        <dt>Failed</dt>
                        <dd class="stat stat--failed">{{ tasks.failed }}</dd>
                      </div>
                      <div>
                        <dt>Aborted</dt>
                        <dd class="stat stat--aborted">{{ tasks.aborted }}</dd>
                      </div>
                      <div>
                        <dt>Cached</dt>
                        <dd class="stat">{{ tasks.cached }}</dd>
                      </div>
                    </dl>
                  } @else {
                    <p class="empty-note">No task data available</p>
                  }
                </section>

                @if (selectedRun.cost !== null || selectedRun.resources) {
                  <section class="section" aria-labelledby="resources-heading-material">
                    <h3 id="resources-heading-material">Cost &amp; resources</h3>
                    <dl class="resource-stats">
                      <div>
                        <dt>
                          {{ selectedRun.status === 'RUNNING' ? 'Estimated cost' : 'Total cost' }}
                        </dt>
                        <dd>{{ selectedRun.costLabel }}</dd>
                      </div>
                      @if (selectedRun.resources; as resources) {
                        <div>
                          <dt>CPU efficiency</dt>
                          <dd>{{ resources.cpuEfficiencyPct }}%</dd>
                        </div>
                        <div>
                          <dt>Peak CPUs</dt>
                          <dd>{{ resources.peakCpus }}</dd>
                        </div>
                        <div>
                          <dt>Memory peak</dt>
                          <dd>{{ resources.memoryPeakLabel }}</dd>
                        </div>
                      }
                    </dl>
                  </section>
                }

                @if (selectedRun.topProcesses.length > 0) {
                  <section class="section" aria-labelledby="processes-heading-material">
                    <h3 id="processes-heading-material">Top resource usage by process</h3>
                    <div class="process-list">
                      @for (process of selectedRun.topProcesses.slice(0, 3); track process.name) {
                        <div class="process">
                          <span class="process__name">{{ process.name }}</span>
                          <div
                            class="process__track"
                            role="img"
                            [attr.aria-label]="
                              process.name + ': ' + process.valuePct + '% resource usage'
                            "
                          >
                            <span class="process__fill" [style.width.%]="process.valuePct"></span>
                          </div>
                          <span class="process__value">{{ process.valuePct }}%</span>
                        </div>
                      }
                    </div>
                  </section>
                }
              </div>
            } @else {
              <div class="placeholder">
                <span class="material-icons placeholder__icon" aria-hidden="true">{{
                  placeholderIcon()
                }}</span>
                <h3>{{ activeTab() }}</h3>
                <p>{{ activeTab() }} details will appear here.</p>
              </div>
            }
          </div>
        }
      </mat-drawer>
    </mat-drawer-container>
  `,
  styleUrl: './run-drawer-material.component.scss',
  host: { class: 'run-drawer-material-host' },
})
export class RunDrawerMaterialComponent {
  readonly run = input<RunDetailVM | null>(null);
  readonly close = output<void>();

  protected readonly tabs: readonly DrawerTab[] = [
    'Overview',
    'Tasks',
    'Metrics',
    'Config',
    'Logs',
  ];
  protected readonly activeTab = signal<DrawerTab>('Overview');
  protected readonly copiedTarget = signal<CopyTarget | null>(null);

  // Kept mounted through MatDrawer's own close transition — `(closed)` (fired
  // once that transition finishes) is what actually clears it, so content
  // doesn't vanish mid-slide the way an `@if (run(); ...)` would.
  protected readonly displayRun = signal<RunDetailVM | null>(null);
  protected readonly isOpen = computed(() => this.run() !== null);

  private readonly document = inject(DOCUMENT);
  private readonly destroyRef = inject(DestroyRef);
  private copyTimer: ReturnType<typeof setTimeout> | null = null;

  protected readonly copyableError = computed(() => {
    const selectedRun = this.displayRun();
    return selectedRun?.error?.raw ?? selectedRun?.commandLine ?? '';
  });

  protected readonly attentionSummary = computed(() => {
    const selectedRun = this.displayRun();
    const failed = selectedRun?.tasks?.failed ?? 0;
    const retries = selectedRun?.retries ?? 0;
    const details: string[] = [];
    if (failed) details.push(`${failed} ${failed === 1 ? 'task' : 'tasks'} failed`);
    if (retries) details.push(`${retries} ${retries === 1 ? 'retry' : 'retries'}`);
    return details.length ? details.join(', ') : 'This run needs attention';
  });

  protected readonly runningSummary = computed(() => {
    const tasks = this.displayRun()?.tasks;
    if (!tasks) return 'Waiting for task data.';
    return `${tasks.succeeded} succeeded · ${tasks.running ?? 0} running of ${tasks.total} tasks`;
  });

  constructor() {
    // MatDrawer owns open/close animation, backdrop, focus-trap, Esc and
    // reduced-motion — this only needs to keep the last run mounted while it
    // plays the exit transition, and reset the tab strip once it's gone.
    effect(() => {
      const incoming = this.run();
      if (incoming) this.displayRun.set(incoming);
    });

    this.destroyRef.onDestroy(() => {
      if (this.copyTimer) clearTimeout(this.copyTimer);
    });
  }

  /** MatDrawer reports its own state changes (Esc, backdrop click, or a bound `opened` flip) here. */
  protected onOpenedChange(opened: boolean): void {
    if (!opened) this.close.emit();
  }

  /** Fires once the close transition finishes — safe to unmount content now. */
  protected onClosed(): void {
    this.displayRun.set(null);
    this.activeTab.set('Overview');
  }

  protected requestClose(): void {
    this.close.emit();
  }

  protected selectTab(tab: DrawerTab): void {
    this.activeTab.set(tab);
  }

  protected onTabKeydown(event: KeyboardEvent): void {
    const currentIndex = this.tabs.indexOf(this.activeTab());
    let nextIndex: number | null = null;

    if (event.key === 'ArrowRight') nextIndex = (currentIndex + 1) % this.tabs.length;
    if (event.key === 'ArrowLeft')
      nextIndex = (currentIndex - 1 + this.tabs.length) % this.tabs.length;
    if (event.key === 'Home') nextIndex = 0;
    if (event.key === 'End') nextIndex = this.tabs.length - 1;
    if (nextIndex === null) return;

    event.preventDefault();
    this.activeTab.set(this.tabs[nextIndex]);
    const tabList = event.currentTarget as HTMLElement;
    queueMicrotask(() => {
      tabList.querySelectorAll<HTMLButtonElement>('[role="tab"]')[nextIndex!]?.focus();
    });
  }

  protected copyError(): void {
    const value = this.copyableError();
    if (value) this.copy(value, 'error');
  }

  protected copyWorkDir(): void {
    const value = this.displayRun()?.workDir;
    if (value && value !== '—') this.copy(value, 'workDir');
  }

  protected placeholderIcon(): string {
    const icons: Record<Exclude<DrawerTab, 'Overview'>, string> = {
      Tasks: 'checklist',
      Metrics: 'query_stats',
      Config: 'tune',
      Logs: 'subject',
    };
    const tab = this.activeTab();
    return tab === 'Overview' ? 'info' : icons[tab];
  }

  private copy(value: string, target: CopyTarget): void {
    this.copiedTarget.set(target);
    void this.document.defaultView?.navigator.clipboard?.writeText(value).catch(() => undefined);

    if (this.copyTimer) clearTimeout(this.copyTimer);
    this.copyTimer = setTimeout(() => this.copiedTarget.set(null), 1200);
  }
}

styleUrlsData.data:
// Outer shell only — MatDrawer/MatDrawerContainer own the slide transition,
// backdrop, focus-trap, Esc and reduced-motion. Everything from `.drawer__header`
// down is the same overview content/styling as `run-drawer`, just re-hosted.

:host {
  display: block;
  height: 100%;
}

.run-drawer-material {
  height: 100%;
  color: var(--c-text);
  // This container is used as a floating overlay sibling of the real page
  // content, not as a wrapper around it (`<mat-drawer-content>` below is
  // intentionally empty) — without this override, Material's own theme
  // paints an opaque background on `mat-drawer-container` that covers
  // whatever real content sits underneath this component's host.
  background: transparent;
}

.run-drawer-material__content {
  height: 100%;
  // Never actually shows content (nothing is projected into it) — must stay
  // transparent for the same reason as `.run-drawer-material` above.
  background: transparent;
}

.run-drawer-material__panel {
  display: flex;
  width: min(680px, 100%);
  flex-direction: column;
  background: var(--c-surface);
  border-left: 1px solid var(--c-border);
  box-shadow: -12px 0 32px rgb(11 31 51 / 14%);
}

.drawer__header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
  padding: 20px 20px 16px 24px;
  border-bottom: 1px solid var(--c-border);
}

.drawer__status {
  padding-top: 3px;
}

.drawer__identity {
  min-width: 0;

  h2 {
    overflow: hidden;
    margin: 0;
    color: var(--c-text);
    font-size: 1.1rem;
    font-weight: 650;
    line-height: 1.4;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

.drawer__context {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  align-items: center;
  margin-top: 4px;
  color: #526477;
  font-size: 0.82rem;
}

.tag {
  padding: 1px 7px;
  color: #475569;
  background: var(--c-cancel-bg);
  border: 1px solid var(--c-cancel-border);
  border-radius: 100px;
  font-size: 0.72rem;
}

.drawer__actions {
  display: flex;
  gap: 2px;
}

.icon-button,
.copy-icon {
  display: inline-grid;
  width: 36px;
  height: 36px;
  padding: 0;
  place-items: center;
  color: #475569;
  background: transparent;
  border: 0;
  border-radius: var(--radius);
  cursor: pointer;

  &:hover {
    color: var(--c-text);
    background: #f1f4f7;
  }

  &:focus-visible {
    outline: 2px solid var(--c-primary);
    outline-offset: 2px;
  }

  .material-icons {
    font-size: 20px;
  }
}

.icon-button--close {
  margin-left: 4px;
}

.tabs {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  padding: 0 20px;
  border-bottom: 1px solid var(--c-border);
}

.tabs__tab {
  position: relative;
  padding: 12px 10px 10px;
  color: #526477;
  background: transparent;
  border: 0;
  cursor: pointer;
  font: inherit;
  font-size: 0.84rem;
  font-weight: 550;
  white-space: nowrap;

  &[aria-selected='true'] {
    color: #3346c8;

    &::after {
      position: absolute;
      right: 8px;
      bottom: -1px;
      left: 8px;
      height: 2px;
      background: var(--c-primary);
      content: '';
    }
  }

  &:focus-visible {
    outline: 2px solid var(--c-primary);
    outline-offset: -2px;
  }
}

.drawer__body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  background: #fbfcfd;

  &:focus-visible {
    outline: 2px solid var(--c-primary);
    outline-offset: -3px;
  }
}

.overview {
  display: grid;
  gap: 12px;
  padding: 20px 24px 32px;
}

.result-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  padding: 16px;
  border: 1px solid;
  border-radius: var(--radius);

  h3 {
    margin: 0;
    font-size: 0.92rem;
    font-weight: 650;
  }

  p {
    margin: 6px 0 0;
  }
}

.result-card__icon {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;

  .material-icons {
    font-size: 21px;
  }
}

.result-card--failed {
  color: var(--c-fail-text);
  background: var(--c-fail-bg);
  border-color: var(--c-fail-border);

  .error-cause {
    color: #851d1d;
    font-family: 'JetBrains Mono Variable', ui-monospace, monospace;
    font-size: 0.82rem;
    line-height: 1.5;
  }
}

.result-card--succeeded {
  color: var(--c-ok-text);
  background: var(--c-ok-bg);
  border-color: var(--c-ok-border);
}

.result-card--running {
  color: var(--c-run-text);
  background: var(--c-run-bg);
  border-color: var(--c-run-border);
}

.result-card__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.button {
  display: inline-flex;
  min-height: 34px;
  gap: 6px;
  align-items: center;
  padding: 6px 10px;
  color: var(--c-text);
  background: var(--c-surface);
  border: 1px solid #c8d1dc;
  border-radius: var(--radius);
  cursor: pointer;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 600;

  .material-icons {
    font-size: 16px;
  }

  &:focus-visible {
    outline: 2px solid var(--c-primary);
    outline-offset: 2px;
  }
}

.button--secondary {
  color: #3346c8;
  border-color: #aeb8f4;
}

.button--disabled {
  color: #68788a;
  background: #f1f3f5;
  border-color: #d9dee4;
  cursor: not-allowed;
}

.attention-note {
  display: flex;
  gap: 6px;
  align-items: center;
  padding-top: 8px;
  color: #92400e;
  border-top: 1px solid var(--c-warn-border);
  font-size: 0.82rem;

  .material-icons {
    font-size: 17px;
  }
}

.section {
  padding: 16px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
