.sort-btn {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  background: none;
  border: none;
  cursor: pointer;
  color: inherit;
  font-size: inherit;
  font-weight: inherit;
  text-transform: inherit;
  letter-spacing: inherit;
  padding: 0;
  border-radius: var(--radius);

  &:focus-visible {
    outline: 2px solid var(--c-primary);
    outline-offset: 3px;
  }

  &--active {
    color: var(--c-primary);
  }
}

.sort-icon {
  font-size: 13px;
  line-height: 1;
  opacity: 0.6;

  .sort-btn--active & {
    opacity: 1;
  }
}

// ─── Paginator ───────────────────────────────────────────────────────────────────

mat-paginator {
  border-top: 1px solid var(--c-border);
  background: var(--c-surface);
}

