.shimmer {
  @include shimmer-base;
  height: 14px;

  &--pill  { width: 72px;  height: 20px; border-radius: var(--radius-pill); }
  &--exec  { width: 80px; }
  &--name  { width: 160px; margin-bottom: 4px; }
  &--pipeline { width: 100px; height: 10px; }
  &--user  { width: 90px; }
  &--text  { width: 60px; }
  &--short { width: 30px; }
  &--bar   { width: 100%; height: 6px; }
}

@media (prefers-reduced-motion: reduce) {
  .shimmer { animation: none; }
}

